package internal

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"

	"github.com/compose-spec/compose-go/v2/cli"
	"github.com/compose-spec/compose-go/v2/types"
)

// ComposeFile returns the absolute path to a compose file discovered in the
// current working directory. It prefers `docker-compose.yaml` over
// `docker-compose.yml`. Returns an error if no file is found.
func ComposeFile() (string, error) {
	for _, name := range []string{"docker-compose.yaml", "docker-compose.yml"} {
		if _, err := os.Stat(name); err == nil {
			abs, err := filepath.Abs(name)
			if err != nil {
				return "", fmt.Errorf("error expanding path: %v", err)
			}
			return abs, nil
		}
	}
	return "", errors.New("no compose file found")
}

// ComposeProject loads a compose project from the given file(s).
func ComposeProject(ctx context.Context, projectName string, filenames []string, profiles []string, envFiles []string) (*types.Project, error) {
	opts := []cli.ProjectOptionsFn{
		cli.WithOsEnv,
		cli.WithEnvFiles(envFiles...),
		cli.WithDotEnv,
		cli.WithDefaultProfiles(profiles...),
		cli.WithName(projectName),
	}

	options, err := cli.NewProjectOptions(filenames, opts...)
	if err != nil {
		return nil, fmt.Errorf("error creating project options: %v", err)
	}

	project, err := options.LoadProject(ctx)
	if err != nil {
		return nil, fmt.Errorf("error loading project: %v", err)
	}

	return project, nil
}

package internal

import (
	"reflect"
	"testing"
)

func TestParseHexAddrIPv4(t *testing.T) {
	cases := map[string]string{
		"0100007F": "127.0.0.1",
		"00000000": "0.0.0.0",
		"0500A8C0": "192.168.0.5",
	}
	for hex, want := range cases {
		got := parseHexAddr(hex)
		if got == nil || got.String() != want {
			t.Fatalf("parseHexAddr(%q) = %v, want %s", hex, got, want)
		}
	}
}

func TestParseHexAddrIPv6(t *testing.T) {
	got := parseHexAddr("00000000000000000000000001000000")
	if got == nil || got.String() != "::1" {
		t.Fatalf("expected ::1, got %v", got)
	}
}

func TestParseHexAddr_BadLength(t *testing.T) {
	if parseHexAddr("ABC") != nil {
		t.Fatal("expected nil for bad input")
	}
}

func TestExtractListeners_ParsesTCPv4(t *testing.T) {
	// Header line, a LISTEN on 0.0.0.0:8080 (1F90),
	// a LISTEN on 127.0.0.1:5432 (skipped — loopback),
	// an ESTABLISHED on 0.0.0.0:443 (skipped — state != 0A).
	text := "===tcp===\n" +
		"  sl  local_address rem_address   st tx_queue rx_queue tr tm->when retrnsmt   uid  timeout inode\n" +
		"   0: 00000000:1F90 00000000:0000 0A 00000000:00000000 00:00000000 00000000     0        0 123 ...\n" +
		"   1: 0100007F:1538 00000000:0000 0A 00000000:00000000 00:00000000 00000000     0        0 124 ...\n" +
		"   2: 00000000:01BB 01020304:1234 01 00000000:00000000 00:00000000 00000000     0        0 125 ...\n"
	got := ExtractListeners(text)
	want := []Listener{{Port: 8080, Protocol: ProtocolTCP}}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("got %+v, want %+v", got, want)
	}
}

func TestExtractListeners_ParsesTCPv6(t *testing.T) {
	text := "===tcp6===\n" +
		"   0: 00000000000000000000000000000000:0BB8 00000000000000000000000000000000:0000 0A ...\n" +
		"   1: 00000000000000000000000001000000:2328 00000000000000000000000000000000:0000 0A ...\n"
	got := ExtractListeners(text)
	want := []Listener{{Port: 3000, Protocol: ProtocolTCP}}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("got %+v, want %+v", got, want)
	}
}

func TestExtractListeners_ParsesUDPListenersOnlyInState07(t *testing.T) {
	// Two UDP entries: 0.0.0.0:53 (state 07 = bound/listening) and
	// 192.168.1.5:40000 (state 01 = connected UDP client — skip).
	text := "===udp===\n" +
		"  sl  local_address rem_address   st tx_queue rx_queue tr tm->when retrnsmt   uid  timeout inode\n" +
		"   0: 00000000:0035 00000000:0000 07 00000000:00000000 00:00000000 00000000     0        0 321 ...\n" +
		"   1: 0501A8C0:9C40 08080808:0035 01 00000000:00000000 00:00000000 00000000     0        0 322 ...\n"
	got := ExtractListeners(text)
	want := []Listener{{Port: 53, Protocol: ProtocolUDP}}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("got %+v, want %+v", got, want)
	}
}

func TestExtractListeners_SkipsLoopbackUDP(t *testing.T) {
	text := "===udp===\n" +
		"   0: 0100007F:1538 00000000:0000 07 ...\n"
	got := ExtractListeners(text)
	if len(got) != 0 {
		t.Fatalf("loopback UDP must be skipped, got %+v", got)
	}
}

func TestExtractListeners_AllFourSectionsMerged(t *testing.T) {
	text := "===tcp===\n" +
		"   0: 00000000:1F90 00000000:0000 0A ...\n" +
		"===tcp6===\n" +
		"   0: 00000000000000000000000000000000:1F90 00000000000000000000000000000000:0000 0A ...\n" +
		"===udp===\n" +
		"   0: 00000000:0035 00000000:0000 07 ...\n" +
		"===udp6===\n" +
		"   0: 00000000000000000000000000000000:0035 00000000000000000000000000000000:0000 07 ...\n"
	got := ExtractListeners(text)
	want := []Listener{
		{Port: 8080, Protocol: ProtocolTCP},
		{Port: 53, Protocol: ProtocolUDP},
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("got %+v, want %+v", got, want)
	}
}

func TestExtractListeners_NoEntriesWithoutSectionMarker(t *testing.T) {
	text := "   0: 00000000:1F90 00000000:0000 0A ...\n"
	got := ExtractListeners(text)
	if len(got) != 0 {
		t.Fatalf("expected no listeners without section marker, got %+v", got)
	}
}

package internal

import (
	"context"
	"testing"

	"github.com/moby/moby/api/types/container"
	dockerClient "github.com/moby/moby/client"
)

// fakeAPIClient implements dockerClient.APIClient by embedding the interface
// and overriding only the methods exercised by the test.
type fakeAPIClient struct {
	dockerClient.APIClient

	closed    bool
	inspected string
}

func (f *fakeAPIClient) Close() error {
	f.closed = true
	return nil
}

func (f *fakeAPIClient) ContainerInspect(ctx context.Context, id string, options dockerClient.ContainerInspectOptions) (dockerClient.ContainerInspectResult, error) {
	f.inspected = id
	return dockerClient.ContainerInspectResult{Container: container.InspectResponse{ID: "full-" + id}}, nil
}

func TestWrapDockerClient_PassesThrough(t *testing.T) {
	fake := &fakeAPIClient{}
	cli := WrapDockerClient(fake)

	info, err := cli.ContainerInspect(context.Background(), "abc")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if fake.inspected != "abc" || info.ID != "full-abc" {
		t.Fatalf("inspect not passed through: inspected=%q id=%q", fake.inspected, info.ID)
	}

	if err := cli.Close(); err != nil {
		t.Fatalf("unexpected close error: %v", err)
	}
	if !fake.closed {
		t.Fatal("expected Close to be passed through")
	}
}

package internal

import (
	"testing"

	"github.com/moby/moby/api/types/container"
)

func TestParseRestartPolicy(t *testing.T) {
	cases := []struct {
		name    string
		policy  string
		detach  bool
		want    container.RestartPolicy
		wantErr string
	}{
		{name: "empty detached", policy: "", detach: true, want: container.RestartPolicy{Name: container.RestartPolicyUnlessStopped}},
		{name: "empty attached", policy: "", detach: false, want: container.RestartPolicy{Name: container.RestartPolicyDisabled}},
		{name: "no detached", policy: "no", detach: true, want: container.RestartPolicy{Name: container.RestartPolicyDisabled}},
		{name: "no attached", policy: "no", detach: false, want: container.RestartPolicy{Name: container.RestartPolicyDisabled}},
		{name: "always", policy: "always", detach: true, want: container.RestartPolicy{Name: container.RestartPolicyAlways}},
		{name: "unless-stopped", policy: "unless-stopped", detach: true, want: container.RestartPolicy{Name: container.RestartPolicyUnlessStopped}},
		{name: "on-failure", policy: "on-failure", detach: true, want: container.RestartPolicy{Name: container.RestartPolicyOnFailure}},
		{name: "on-failure with count", policy: "on-failure:5", detach: true, want: container.RestartPolicy{Name: container.RestartPolicyOnFailure, MaximumRetryCount: 5}},
		{name: "negative count", policy: "on-failure:-1", detach: true, wantErr: "invalid restart policy: maximum retry count cannot be negative"},
		{name: "non-integer count", policy: "on-failure:x", detach: true, wantErr: "invalid restart policy format: maximum retry count must be an integer"},
		{name: "count on always", policy: "always:3", detach: true, wantErr: "invalid restart policy: maximum retry count can only be used with 'on-failure'"},
		{name: "missing name", policy: ":3", detach: true, wantErr: "invalid restart policy format: no policy provided before colon"},
		{name: "unknown", policy: "sometimes", detach: true, wantErr: "invalid restart policy: unknown policy 'sometimes'; use one of 'no', 'always', 'on-failure', or 'unless-stopped'"},
		{name: "always attached", policy: "always", detach: false, wantErr: "conflicting options: cannot specify both --restart and an attached (auto-removed) helper; use --detach"},
		{name: "on-failure attached", policy: "on-failure:2", detach: false, wantErr: "conflicting options: cannot specify both --restart and an attached (auto-removed) helper; use --detach"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got, err := ParseRestartPolicy(tc.policy, tc.detach)
			if tc.wantErr != "" {
				if err == nil {
					t.Fatalf("expected error %q, got policy %+v", tc.wantErr, got)
				}
				if err.Error() != tc.wantErr {
					t.Fatalf("got error %q, want %q", err.Error(), tc.wantErr)
				}
				return
			}
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if got != tc.want {
				t.Fatalf("got %+v, want %+v", got, tc.want)
			}
		})
	}
}

package internal

import "testing"

func TestParsePortSpec(t *testing.T) {
	cases := []struct {
		name    string
		in      string
		want    PortPair
		wantErr bool
	}{
		{"same port", "8080", PortPair{LocalPort: 8080, RemotePort: 8080, Protocol: ProtocolTCP}, false},
		{"explicit local", "8888:8080", PortPair{LocalPort: 8888, RemotePort: 8080, Protocol: ProtocolTCP}, false},
		{"auto local", ":8080", PortPair{LocalPort: 0, RemotePort: 8080, Protocol: ProtocolTCP}, false},
		{"trims whitespace", "  80:80  ", PortPair{LocalPort: 80, RemotePort: 80, Protocol: ProtocolTCP}, false},
		{"explicit tcp suffix", "80:80/tcp", PortPair{LocalPort: 80, RemotePort: 80, Protocol: ProtocolTCP}, false},
		{"udp suffix same port", "53/udp", PortPair{LocalPort: 53, RemotePort: 53, Protocol: ProtocolUDP}, false},
		{"udp explicit local", "5353:53/udp", PortPair{LocalPort: 5353, RemotePort: 53, Protocol: ProtocolUDP}, false},
		{"udp auto local", ":53/udp", PortPair{LocalPort: 0, RemotePort: 53, Protocol: ProtocolUDP}, false},
		{"udp uppercase", "53:53/UDP", PortPair{LocalPort: 53, RemotePort: 53, Protocol: ProtocolUDP}, false},
		{"empty", "", PortPair{}, true},
		{"bad local", "abc:80", PortPair{}, true},
		{"bad remote", "80:abc", PortPair{}, true},
		{"remote zero", "80:0", PortPair{}, true},
		{"remote zero bare", "0", PortPair{}, true},
		{"out of range", "99999", PortPair{}, true},
		{"out of range local", "99999:80", PortPair{}, true},
		{"unknown protocol rejected", "53/sctp", PortPair{}, true},
		{"empty protocol rejected", "53/", PortPair{}, true},
		{"missing port before proto", "/udp", PortPair{}, true},
		{"negative", "-1:80", PortPair{}, true},
		{"ipv4 address", "127.0.0.1:8080:80", PortPair{Address: "127.0.0.1", LocalPort: 8080, RemotePort: 80, Protocol: ProtocolTCP}, false},
		{"all interfaces", "0.0.0.0:5432:5432", PortPair{Address: "0.0.0.0", LocalPort: 5432, RemotePort: 5432, Protocol: ProtocolTCP}, false},
		{"localhost address", "localhost:8080:80", PortPair{Address: "localhost", LocalPort: 8080, RemotePort: 80, Protocol: ProtocolTCP}, false},
		{"address auto local", "127.0.0.1::80", PortPair{Address: "127.0.0.1", LocalPort: 0, RemotePort: 80, Protocol: ProtocolTCP}, false},
		{"address udp", "0.0.0.0:5353:53/udp", PortPair{Address: "0.0.0.0", LocalPort: 5353, RemotePort: 53, Protocol: ProtocolUDP}, false},
		{"bracketed ipv6", "[::1]:8080:80", PortPair{Address: "::1", LocalPort: 8080, RemotePort: 80, Protocol: ProtocolTCP}, false},
		{"bracketed ipv6 auto local udp", "[::]::53/udp", PortPair{Address: "::", LocalPort: 0, RemotePort: 53, Protocol: ProtocolUDP}, false},
		{"unbracketed ipv6", "::1:8080:80", PortPair{}, true},
		{"hostname address", "example.com:8080:80", PortPair{}, true},
		{"partial ip address", "1.2.3:80:80", PortPair{}, true},
		{"all interfaces keyword", "*:8080:80", PortPair{Address: "*", LocalPort: 8080, RemotePort: 80, Protocol: ProtocolTCP}, false},
		{"all interfaces keyword auto local", "*::80", PortPair{Address: "*", LocalPort: 0, RemotePort: 80, Protocol: ProtocolTCP}, false},
		{"all interfaces udp", "*:53:53/udp", PortPair{Address: "*", LocalPort: 53, RemotePort: 53, Protocol: ProtocolUDP}, false},
		{"docker empty host ip", ":8080:80", PortPair{Address: "*", LocalPort: 8080, RemotePort: 80, Protocol: ProtocolTCP}, false},
		{"docker empty host ip auto local", "::80", PortPair{Address: "*", LocalPort: 0, RemotePort: 80, Protocol: ProtocolTCP}, false},
		{"empty brackets", "[]:8080:80", PortPair{}, true},
		{"bracketed ipv4", "[127.0.0.1]:8080:80", PortPair{}, true},
		{"unclosed bracket", "[::1:8080:80", PortPair{}, true},
		{"bracket without local", "[::1]:80", PortPair{}, true},
		{"too many parts", "1.2.3.4:1:2:3", PortPair{}, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got, err := ParsePortSpec(tc.in)
			if tc.wantErr {
				if err == nil {
					t.Fatalf("expected error for %q, got %+v", tc.in, got)
				}
				return
			}
			if err != nil {
				t.Fatalf("unexpected error for %q: %v", tc.in, err)
			}
			if got != tc.want {
				t.Fatalf("for %q: got %+v, want %+v", tc.in, got, tc.want)
			}
		})
	}
}

func TestParsePortSpecs(t *testing.T) {
	t.Run("multiple including udp", func(t *testing.T) {
		got, err := ParsePortSpecs([]string{"80", "8888:8080", ":5000", "53:53/udp"})
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		want := []PortPair{
			{LocalPort: 80, RemotePort: 80, Protocol: ProtocolTCP},
			{LocalPort: 8888, RemotePort: 8080, Protocol: ProtocolTCP},
			{LocalPort: 0, RemotePort: 5000, Protocol: ProtocolTCP},
			{LocalPort: 53, RemotePort: 53, Protocol: ProtocolUDP},
		}
		if len(got) != len(want) {
			t.Fatalf("got %d pairs, want %d", len(got), len(want))
		}
		for i := range want {
			if got[i] != want[i] {
				t.Fatalf("pair %d: got %+v, want %+v", i, got[i], want[i])
			}
		}
	})

	t.Run("empty", func(t *testing.T) {
		_, err := ParsePortSpecs(nil)
		if err == nil {
			t.Fatal("expected error on empty specs")
		}
	})

	t.Run("first invalid stops", func(t *testing.T) {
		_, err := ParsePortSpecs([]string{"bad", "80"})
		if err == nil {
			t.Fatal("expected error on bad spec")
		}
	})
}

func TestPortPairString(t *testing.T) {
	cases := map[string]PortPair{
		"80:80":               {LocalPort: 80, RemotePort: 80},
		":8080":               {LocalPort: 0, RemotePort: 8080},
		"53:53/udp":           {LocalPort: 53, RemotePort: 53, Protocol: ProtocolUDP},
		":53/udp":             {LocalPort: 0, RemotePort: 53, Protocol: ProtocolUDP},
		"127.0.0.1:8080:80":   {Address: "127.0.0.1", LocalPort: 8080, RemotePort: 80},
		"0.0.0.0::80":         {Address: "0.0.0.0", LocalPort: 0, RemotePort: 80},
		"[::1]:5353:53/udp":   {Address: "::1", LocalPort: 5353, RemotePort: 53, Protocol: ProtocolUDP},
		"localhost:9000:9000": {Address: "localhost", LocalPort: 9000, RemotePort: 9000},
		"*:8080:80":           {Address: "*", LocalPort: 8080, RemotePort: 80},
		"*::53/udp":           {Address: "*", LocalPort: 0, RemotePort: 53, Protocol: ProtocolUDP},
	}
	for want, in := range cases {
		got := in.String()
		if got != want {
			t.Fatalf("got %q, want %q", got, want)
		}
		// Every rendered form parses back to the same pair.
		parsed, err := ParsePortSpec(got)
		if err != nil {
			t.Fatalf("round-trip of %q failed: %v", got, err)
		}
		in.Protocol = NormalizeProtocol(in.Protocol)
		if parsed != in {
			t.Fatalf("round-trip of %q: got %+v, want %+v", got, parsed, in)
		}
	}
}

func TestNormalizeProtocol(t *testing.T) {
	if got := NormalizeProtocol(""); got != ProtocolTCP {
		t.Fatalf("empty → %q, want tcp", got)
	}
	if got := NormalizeProtocol(ProtocolTCP); got != ProtocolTCP {
		t.Fatalf("tcp unchanged, got %q", got)
	}
	if got := NormalizeProtocol(ProtocolUDP); got != ProtocolUDP {
		t.Fatalf("udp unchanged, got %q", got)
	}
}

func TestValidateAddress(t *testing.T) {
	for _, ok := range []string{"127.0.0.1", "0.0.0.0", "::1", "::", "localhost", "*"} {
		if err := ValidateAddress(ok); err != nil {
			t.Fatalf("expected %q to be valid: %v", ok, err)
		}
	}
	err := ValidateAddress("example.com")
	if err == nil || err.Error() != `invalid address "example.com": must be an IP address, "localhost" or "*"` {
		t.Fatalf("unexpected error: %v", err)
	}
}

func TestValidateAddresses(t *testing.T) {
	for _, ok := range [][]string{nil, {"localhost"}, {"127.0.0.1", "::1"}, {"*"}} {
		if err := ValidateAddresses(ok); err != nil {
			t.Fatalf("expected %v to be valid: %v", ok, err)
		}
	}
	err := ValidateAddresses([]string{"localhost", "example.com"})
	if err == nil || err.Error() != `invalid --address value "example.com": must be an IP address, "localhost" or "*"` {
		t.Fatalf("unexpected error: %v", err)
	}
	err = ValidateAddresses([]string{"*", "127.0.0.1"})
	if err == nil || err.Error() != `invalid --address value "*": cannot be combined with other addresses` {
		t.Fatalf("unexpected error: %v", err)
	}
}

package internal

import (
	"context"
	"fmt"
	"testing"

	cerrdefs "github.com/containerd/errdefs"
	"github.com/moby/moby/api/types/container"
	dockerClient "github.com/moby/moby/client"
)

func TestParseTarget(t *testing.T) {
	cases := []struct {
		in       string
		wantType TargetType
		wantName string
		wantErr  bool
	}{
		{"container/foo", TargetTypeContainer, "foo", false},
		{"container/abc123", TargetTypeContainer, "abc123", false},
		{"service/web", TargetTypeService, "web", false},
		{"web", TargetTypeAuto, "web", false},
		{"  trimmed  ", TargetTypeAuto, "trimmed", false},
		{"", "", "", true},
		{"container/", "", "", true},
		{"service/", "", "", true},
	}
	for _, tc := range cases {
		t.Run(tc.in, func(t *testing.T) {
			got, err := ParseTarget(tc.in)
			if tc.wantErr {
				if err == nil {
					t.Fatalf("expected error for %q", tc.in)
				}
				return
			}
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if got.Type != tc.wantType || got.Name != tc.wantName {
				t.Fatalf("got %+v, want type=%q name=%q", got, tc.wantType, tc.wantName)
			}
		})
	}
}

func TestResolveTarget_ContainerPrefix(t *testing.T) {
	cli := &mockDockerClient{
		containerInspect: func(ctx context.Context, id string) (container.InspectResponse, error) {
			if id != "foo" {
				t.Fatalf("expected inspect id=foo, got %q", id)
			}
			return container.InspectResponse{
				ID:    "sha-foo",
				Name:  "/foo",
				State: &container.State{Running: true},
			}, nil
		},
	}
	got, err := ResolveTarget(context.Background(), ResolveTargetInput{
		Client: cli,
		Target: ParsedTarget{Type: TargetTypeContainer, Name: "foo"},
	})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got.ContainerID != "sha-foo" || got.ContainerName != "foo" {
		t.Fatalf("got %+v", got)
	}
}

func TestResolveTarget_ContainerNotRunning(t *testing.T) {
	cli := &mockDockerClient{
		containerInspect: func(ctx context.Context, id string) (container.InspectResponse, error) {
			return container.InspectResponse{
				ID:    "sha-foo",
				Name:  "/foo",
				State: &container.State{Running: false},
			}, nil
		},
	}
	_, err := ResolveTarget(context.Background(), ResolveTargetInput{
		Client: cli,
		Target: ParsedTarget{Type: TargetTypeContainer, Name: "foo"},
	})
	if err == nil {
		t.Fatal("expected error for non-running container")
	}
}

func TestResolveTarget_ServicePicksLowestInstance(t *testing.T) {
	cli := &mockDockerClient{
		containerList: func(ctx context.Context, options dockerClient.ContainerListOptions) ([]container.Summary, error) {
			// Assert the filter was set correctly for project + service.
			values := options.Filters["label"]
			if !values[ComposeProjectLabel+"=proj"] || !values[ComposeServiceLabel+"=web"] {
				t.Fatalf("missing label filters in %v", values)
			}
			return []container.Summary{
				{
					ID:     "sha-2",
					Names:  []string{"/proj-web-2"},
					State:  "running",
					Labels: map[string]string{ComposeContainerNumLabel: "2"},
				},
				{
					ID:     "sha-1",
					Names:  []string{"/proj-web-1"},
					State:  "running",
					Labels: map[string]string{ComposeContainerNumLabel: "1"},
				},
			}, nil
		},
	}

	got, err := ResolveTarget(context.Background(), ResolveTargetInput{
		Client:      cli,
		Target:      ParsedTarget{Type: TargetTypeService, Name: "web"},
		ProjectName: "proj",
	})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got.ContainerID != "sha-1" || got.ContainerName != "proj-web-1" {
		t.Fatalf("expected lowest-numbered replica, got %+v", got)
	}
}

func TestResolveTarget_ServiceNoRunning(t *testing.T) {
